import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, Message, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

// Each provider call consumes the next round of chunks, so every round can report its own usage.
const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (result: string): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
    result,
  }));
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};

const toolRoundStop = (usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'tool_use', usage});
const finalStop = (usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'end_turn', usage});

// Runs one user turn and returns whatever usage the afterModelResponse hook was handed.
const usageReportedFor = async (rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> => {
  let reported: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, usage) => {
      reported = usage;
    },
  };
  const orchestrator = createChatOrchestrator(scriptedProvider(rounds), promptBuilder, registryReturning('r'), {hooks});
  await orchestrator.processMessage(createSession('ask'));
  return reported;
};

describe('ChatOrchestrator usage across tool rounds', () => {
  it('reports the summed usage of every provider call in a turn that ran two tool rounds', async () => {
    const reported = await usageReportedFor([
      [TOOL_CALL, toolRoundStop({inputTokens: 100, outputTokens: 10, totalTokens: 110})],
      [TOOL_CALL, toolRoundStop({inputTokens: 250, outputTokens: 20, totalTokens: 270})],
      [{type: 'text', text: 'done'}, finalStop({inputTokens: 400, outputTokens: 30, totalTokens: 430})],
    ]);

    expect(reported).toEqual({inputTokens: 750, outputTokens: 60, totalTokens: 810});
  });

  it('sums only the rounds that reported usage, and reports nothing when no round did', async () => {
    const someSilent = await usageReportedFor([
      [TOOL_CALL, toolRoundStop({inputTokens: 100, outputTokens: 10, totalTokens: 110})],
      [TOOL_CALL, toolRoundStop()],
      [{type: 'text', text: 'done'}, finalStop({inputTokens: 400, outputTokens: 30, totalTokens: 430})],
    ]);
    expect(someSilent).toEqual({inputTokens: 500, outputTokens: 40, totalTokens: 540});

    const noneReported = await usageReportedFor([
      [TOOL_CALL, toolRoundStop()],
      [{type: 'text', text: 'done'}, finalStop()],
    ]);
    expect(noneReported).toBeUndefined();
  });
});

